using System;using System.Diagnostics;using System.IO;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
namespace TrayLeaf {
 public sealed partial class Controller {
  CancellationTokenSource updateDownload;ReleaseInfo availableRelease;Grid aboutHost;FlowDocumentScrollViewer changelogView;TextBlock changelogStatus;bool changelogLoading,changelogLoaded,changelogReloadRequested;
  internal Func<string,CancellationToken,Task<string>> changelogFetcher=(url,token)=>UpdateService.GetText(url,10000,token);
  void SetupAbout100(){var about=Get<ScrollViewer>("AboutPanel");var parent=(Grid)about.Parent;int index=parent.Children.IndexOf(about);parent.Children.Remove(about);aboutHost=FeatureUi.Parse("<Grid.ColumnDefinitions><ColumnDefinition Width='154'/><ColumnDefinition Width='*'/></Grid.ColumnDefinitions><StackPanel x:Name='Side' Margin='0,0,20,0'/>");Grid.SetRow(aboutHost,1);aboutHost.Visibility=Visibility.Collapsed;parent.Children.Insert(index,aboutHost);Grid.SetColumn(about,1);aboutHost.Children.Add(about);
   var content=new Grid();content.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});content.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});var bar=new DockPanel{Margin=new Thickness(0,0,0,12)};changelogStatus=FeatureUi.Label("更新内容",true);var retry=FeatureUi.Button("刷新",async delegate{await LoadChangelog();},false);DockPanel.SetDock(retry,Dock.Right);bar.Children.Add(retry);bar.Children.Add(changelogStatus);content.Children.Add(bar);changelogView=new FlowDocumentScrollViewer{IsToolBarVisible=false,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,Background=Brushes.Transparent};Grid.SetRow(changelogView,1);content.Children.Add(changelogView);Grid.SetColumn(content,1);content.Visibility=Visibility.Collapsed;aboutHost.Children.Add(content);ScrollActivity.Attach(changelogView);
   var side=(StackPanel)aboutHost.FindName("Side");Button aboutTab=null,logTab=null;Action<bool> select=async showLog=>{about.Visibility=showLog?Visibility.Collapsed:Visibility.Visible;content.Visibility=showLog?Visibility.Visible:Visibility.Collapsed;foreach(var item in new[]{aboutTab,logTab}){item.SetResourceReference(Control.ForegroundProperty,(item==logTab)==showLog?"Accent":"Muted");item.SetResourceReference(Control.BorderBrushProperty,(item==logTab)==showLog?"Accent":"TransparentNavigationBorder");}if(showLog&&!changelogLoaded&&!changelogLoading)await LoadChangelog();};aboutTab=FeatureUi.Button("关于",()=>select(false),false);logTab=FeatureUi.Button("更新内容",()=>select(true),false);foreach(var b in new[]{aboutTab,logTab}){b.SetResourceReference(FrameworkElement.StyleProperty,"Nav");b.Margin=new Thickness(0,0,0,4);side.Children.Add(b);}select(false);
   RefreshChangelogOnStart();
   downloadButton=FeatureUi.Button("下载更新",DownloadUpdate,true);downloadButton.HorizontalAlignment=HorizontalAlignment.Right;downloadButton.Visibility=Visibility.Collapsed;var card=(StackPanel)Get<Button>("OpenReleaseButton").Parent;card.Children.Add(downloadButton);
  }
  void RefreshChangelogOnStart(){if(demo)return;w.Dispatcher.BeginInvoke(new Action(async delegate{await LoadChangelog();}));}
  async Task LoadChangelog(){if(changelogLoading){changelogReloadRequested=true;return;}changelogLoading=true;changelogStatus.Text=UiLanguage.Text("正在获取更新内容…");try{string text=await changelogFetcher("https://raw.githubusercontent.com/yunnikuu/TrayLeaf/main/CHANGELOG.md?session="+Guid.NewGuid().ToString("N"),CancellationToken.None);changelogView.Document=MarkdownView.Render(text,w);changelogLoaded=true;changelogStatus.Text=UiLanguage.Text("更新内容 · GitHub CHANGELOG.md");}catch(Exception ex){changelogStatus.Text=UiLanguage.Text("获取失败：")+ex.Message;}finally{changelogLoading=false;}if(changelogReloadRequested){changelogReloadRequested=false;await LoadChangelog();}}
  async void DownloadUpdate(){if(updateDownload!=null){updateDownload.Cancel();return;}updateDownload=new CancellationTokenSource();var token=updateDownload.Token;downloadButton.Content=UiLanguage.Text("取消下载");Get<TextBlock>("UpdateStatus").Visibility=Visibility.Visible;try{if(busy)throw new IOException("请先等待关闭或恢复操作完成");Text("UpdateStatus","正在读取安装包信息…");var release=await UpdateService.GetRelease(token);if(!UpdateService.IsNewer(release.Tag,AppIdentity.ReleaseVersion))throw new IOException("当前已是最新版本");availableRelease=release;string directory=Path.Combine(Path.GetDirectoryName(db.FilePath),"updates");string file=await UpdateService.Download(release,directory,percent=>w.Dispatcher.BeginInvoke(new Action(()=>Text("UpdateStatus","正在下载安装包 "+percent+"%"))),token);token.ThrowIfCancellationRequested();if(!UpdateService.VerifyDigest(file,release.Digest))throw new IOException("安装前复核 SHA-256 失败，已取消安装");Text("UpdateStatus","校验通过，正在启动安装程序…");if(liveTimer!=null&&liveTimer.IsEnabled)SaveLiveSettings();var start=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"msiexec.exe"),"/i "+StartupManager.Quote(file)){UseShellExecute=true};using(var process=Process.Start(start)){if(process==null)throw new IOException("Windows Installer 未能启动");}Exit();}catch(OperationCanceledException){Text("UpdateStatus","下载已取消");}catch(System.Net.WebException ex){Text("UpdateStatus",token.IsCancellationRequested?"下载已取消":"下载失败："+ex.Message);}catch(Exception ex){Text("UpdateStatus","更新失败："+ex.Message);}finally{updateDownload.Dispose();updateDownload=null;downloadButton.Content=UiLanguage.Text("下载更新");}}
 }
}
